/* Smooth section navigation and eased mouse-wheel scrolling.
   Native touch/trackpad gestures, form panels and reduced-motion remain native. */
(()=>{const reduced=matchMedia('(prefers-reduced-motion: reduce)'),desktop=matchMedia('(min-width:801px) and (hover:hover) and (pointer:fine)');let frame=0,target=0,last=0,current=0;const clamp=y=>Math.max(0,Math.min(y,document.documentElement.scrollHeight-innerHeight));function stop(){if(frame)cancelAnimationFrame(frame);frame=0;last=0;target=current=scrollY}function tick(time){const dt=Math.min(40,last?time-last:16);last=time;const y=current,diff=target-y;if(Math.abs(diff)<.6){window.scrollTo({top:target,behavior:'instant'});frame=0;last=0;return}current=clamp(y+diff*(1-Math.exp(-dt/72)));window.scrollTo({top:current,behavior:'instant'});frame=requestAnimationFrame(tick)}function scrollableChild(node){for(let el=node instanceof Element?node:null;el&&el!==document.body;el=el.parentElement){const css=getComputedStyle(el);if((css.overflowY==='auto'||css.overflowY==='scroll')&&el.scrollHeight>el.clientHeight+1)return true}return false}
addEventListener('wheel',event=>{if(reduced.matches||!desktop.matches||event.ctrlKey||event.metaKey||event.shiftKey||Math.abs(event.deltaX)>Math.abs(event.deltaY)||!event.deltaY||document.querySelector('dialog[open]')||scrollableChild(event.target))return;
// Pixel-sized trackpad deltas already have native inertia; only ease wheel steps.
if(event.deltaMode===0&&Math.abs(event.deltaY)<50){stop();return}const delta=event.deltaY*(event.deltaMode===1?16:event.deltaMode===2?innerHeight:1);if(!frame)target=current=scrollY;target=clamp(target+delta);if((scrollY<=0&&delta<0)||(scrollY>=document.documentElement.scrollHeight-innerHeight-1&&delta>0))return;event.preventDefault();if(!frame)frame=requestAnimationFrame(tick)},{passive:false});
addEventListener('pointerdown',stop,{passive:true});addEventListener('keydown',stop);addEventListener('resize',stop);reduced.addEventListener('change',stop);desktop.addEventListener('change',stop);
document.addEventListener('click',event=>{if(event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;const link=event.target.closest?.('a[href^="#"]');if(!link||link.closest('.chapter-tabs')||link.hasAttribute('download'))return;const hash=link.getAttribute('href');let destination;if(hash==='#')destination=0;else{let section;try{section=document.getElementById(decodeURIComponent(hash.slice(1)))}catch{}if(!section)return;destination=section.getBoundingClientRect().top+scrollY-document.querySelector('nav').getBoundingClientRect().height-16}event.preventDefault();stop();if(location.hash!==hash)history.pushState(null,'',hash);window.scrollTo({top:clamp(destination),behavior:reduced.matches?'instant':'smooth'})});
})();
